insert into public.products (id, slug, name, type, collection_ids, description, details, images, tags, status, featured, sold_out, badge, sort_order, price_paise, compare_at_paise, min_qty, options, custom_fields) values ('p-lofi-super-sheet', 'lofi-super-sheet', 'Lo-fi super sheet', 'sheet', array['c-lofi']::text[], 'A whole sheet of lo-fi stickers. The best value per sticker.', 'A super sheet packed with stickers. More than 10 sheets? They drop to the bulk price automatically.', array['/lofi/lofi-09.webp', '/lofi/lofi-12.webp']::text[], array[]::text[], 'live', true, false, 'Best value', 0, 8000, null, 1, '[{"id":"material","name":"Material","values":[{"id":"paper-vinyl","label":"Paper vinyl","priceDeltaPaise":0},{"id":"waterproof","label":"Waterproof","priceDeltaPaise":0}]}]'::jsonb, '[{"id":"designs","label":"Designs you want on the sheet","kind":"textarea","required":false,"help":"List design names, or leave blank and we''ll pick a mix."}]'::jsonb) on conflict (id) do nothing;
insert into public.products (id, slug, name, type, collection_ids, description, details, images, tags, status, featured, sold_out, badge, sort_order, price_paise, compare_at_paise, min_qty, options, custom_fields) values ('p-custom-poster', 'custom-poster', 'Your poster', 'poster', array[]::text[], 'Pick a design and we''ll print it as a poster. A4 or A3, sticker or normal, framed or not.', 'A4 (21 × 29.7 cm) or A3 (29.7 × 42 cm). Sticker posters peel and paste straight onto the wall: no frame, no nails.', array['/lofi/lofi-03.webp']::text[], array[]::text[], 'live', false, false, '', 0, 6000, null, 1, '[{"id":"size","name":"Size","values":[{"id":"a4","label":"A4","priceDeltaPaise":0},{"id":"a3","label":"A3","priceDeltaPaise":4000},{"id":"a4-framed","label":"A4 framed","priceDeltaPaise":14000},{"id":"a3-framed","label":"A3 framed","priceDeltaPaise":34000}]},{"id":"print","name":"Print","values":[{"id":"normal","label":"Normal print","priceDeltaPaise":0},{"id":"sticker","label":"Sticker (peel and paste)","priceDeltaPaise":0}]}]'::jsonb, '[{"id":"design","label":"Which design?","kind":"text","required":false,"help":"A design name from the shop, or describe what you want."}]'::jsonb) on conflict (id) do nothing;
insert into public.products (id, slug, name, type, collection_ids, description, details, images, tags, status, featured, sold_out, badge, sort_order, price_paise, compare_at_paise, min_qty, options, custom_fields) values ('p-music-card', 'music-card', 'Music card', 'music-card', array[]::text[], 'Dedicate a song. Your photo or the album cover with a scannable Spotify code. Minimum 5 cards per order.', 'A scannable Spotify code with your photo or the album cover. Scan it with Spotify and the song plays.', array['/lofi/lofi-15.webp']::text[], array[]::text[], 'live', true, false, 'Gift', 0, 2000, null, 5, '[]'::jsonb, '[{"id":"song","label":"Spotify song link","kind":"link","required":true,"help":"In Spotify: Share → Copy link, then paste it here."},{"id":"photo","label":"Your photo","kind":"image","required":false,"help":"Leave blank to use the album cover."},{"id":"for","label":"Dedicated to","kind":"text","required":false,"help":"A name, a nickname, an inside joke."},{"id":"message","label":"Message on the card","kind":"textarea","required":false,"help":"Optional. Keep it short."}]'::jsonb) on conflict (id) do nothing;
